import { mountFacilityAtlas } from './atlas.js';

export const HC = 1.239841984;
export const CORE_METRICS = ['spectrum','pulse','pulseEnergy','rate','bandwidth','polarization'];
export const CORE_LABELS = {spectrum:'光子能量 / 波长',pulse:'光子脉宽',pulseEnergy:'单脉冲能量',rate:'重复率与供光结构',bandwidth:'光谱带宽',polarization:'偏振能力'};
export function energyRange(row){return row.keV??(row.nm?.length===2?[HC/row.nm[1],HC/row.nm[0]]:null);}
export function overlaps(row,energy){const r=energyRange(row);return !energy||row.spectrumKind!=='condition'&&!!r&&r[0]<=energy&&energy<=r[1];}
export function sortRows(rows,key,dir=1){const value=r=>key==='energy'?energyRange(r)?.[1]:key==='name'?r.facility:r.metrics[key]?.n;
 return [...rows].sort((a,b)=>{const x=value(a),y=value(b);if(x==null)return y==null?a.id.localeCompare(b.id):1;if(y==null)return -1;return (typeof x==='string'?x.localeCompare(y):x-y)*dir||a.id.localeCompare(b.id);});}
export function validSelection(ids,items){const existing=[...new Set(ids)].filter(id=>items.some(row=>row.id===id)),level=items.find(row=>row.id===existing[0])?.level;return existing.filter(id=>items.find(row=>row.id===id)?.level===level).slice(0,4);}
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatRange=values=>values?(values[0]===values[1]?[values[0]]:values).map(v=>Number(v.toPrecision(3))).join('–'):'待补充';
const known=metric=>metric&&metric.text!=='待补充';
const stagePriority={operation:4,projection:3,specification:2,history:1};
export function defaultConfiguration(rows){return [...rows].filter(r=>r.display.role==='capability'&&r.spectrumKind!=='condition').sort((a,b)=>stagePriority[b.category]-stagePriority[a.category]||(b.display.sourceDate??'').localeCompare(a.display.sourceDate??'')||Number(b.mode==='SASE')-Number(a.mode==='SASE')||a.id.localeCompare(b.id))[0]??null;}
export function configurationStatus(row){if(!row)return '当前分支参数待补';if(row.display.role==='condition')return '论文特定工况';return {operation:'运行依据',projection:'预计运行资料',specification:'仅有设计 / 规格',history:'仅有历史资料'}[row.category];}
export function buildFacilityGroups(data,options={}){
 const query=(options.search??'').trim().toLowerCase(),level=options.level??'source',mode=options.mode??'';
 return data.profiles.map(profile=>{const all=data.items.filter(r=>r.display.facilityId===profile.id);
  const branches=profile.branches.filter(branch=>branch.level===level).map(branch=>{const rows=all.filter(r=>r.display.branchId===branch.id);
   const modes=[...new Set([...branch.modes,...rows.filter(r=>r.display.role==='capability').map(r=>r.mode)])];
   const modeRows=modes.map(name=>({mode:name,row:defaultConfiguration(rows.filter(r=>r.mode===name))}));
   const activeMode=mode||options.activeModes?.[`${profile.id}:${branch.id}`]||defaultConfiguration(rows)?.mode||branch.modes[0];
   const active=modeRows.find(entry=>entry.mode===activeMode)?.row??null,primaryIds=new Set(modeRows.filter(entry=>entry.row).map(entry=>entry.row.id));
   return {branch,rows,modes,modeRows,activeMode,active,history:rows.filter(r=>!primaryIds.has(r.id))};
  }).filter(entry=>(!mode||entry.modes.includes(mode))&&(!query||[profile.name,profile.region,profile.felType,profile.accelerator,entry.branch.name,entry.branch.band,...entry.modes,...entry.rows.map(r=>r.branch)].join(' ').toLowerCase().includes(query))&&(!options.energy||entry.active&&overlaps(entry.active,options.energy)));
  return {profile,branches,history:all.filter(r=>r.display.role==='facility-history')};
 }).filter(group=>group.branches.length).sort((a,b)=>a.profile.name.localeCompare(b.profile.name,'en'));
}
function spectrumText(row,unit='keV'){return `${formatRange(unit==='nm'?row.nm:energyRange(row))} ${unit}${row.spectrumKind==='condition'?' · 论文工况':''}`;}
export function coreValue(row,key,unit='keV'){
 if(!row)return {text:'待补充',definition:'尚未收录此模式的可核实参数'};
 if(key==='spectrum')return {text:spectrumText(row,unit),definition:`${formatRange(unit==='nm'?energyRange(row):row.nm)} ${unit==='nm'?'keV':'nm'} · ${row.level==='instrument'?'端站':'源端'}`};
 if(key==='rate'){const average=row.metrics.averageRate,details=[['trainRate','串频'],['intraRate','串内'],['pulsesPerTrain','每串']].filter(([name])=>known(row.metrics[name])&&row.metrics[name].text!=='不适用').map(([name,label])=>`${label}：${row.metrics[name].text}${row.metrics[name].definition?`（${row.metrics[name].definition}）`:''}`);
  return {text:known(average)?average.text:details.length?'平均供光率：未收录':'待补充',definition:[average?.definition?`平均供光率口径：${average.definition}`:'',...details].filter(Boolean).join('；')||'串内频率与平均供光率分开记录'};}
 return row.metrics[key]??{text:'待补充',definition:''};
}
const badge=row=>`<span class="facility-badge ${row?.category??'missing'}">${esc(configurationStatus(row))}</span>`;
function facilityMeta(profile,count,level='source'){return [profile.region,profile.institution, count+'个'+(level==='instrument'?'端站':'分支')].filter(Boolean).join(' · ');}
function facilityContext(profile){return profile.description?`<section class="facility-overview"><span class="facility-kicker">设施概况</span><p>${esc(profile.description)}</p>${profile.institutionName?`<small>研究机构：${esc(profile.institutionName)}</small>`:''}</section>`:'';}
function dimension(label,value){return `<span class="facility-dimension"><span>${label}</span><b>${esc(value)}</b></span>`;}
function classification(profile,branches){return dimension('波段',[...new Set(branches.flatMap(b=>b.band.split('、')).map(b=>b.trim()).filter(Boolean))].join('、'))+dimension('工作方式',profile.felType)+dimension('模式',[...new Set(branches.flatMap(b=>b.modes))].join('、'))+dimension('加速与供束',`${profile.accelerator} · ${profile.pulseStructure}`);}
function metricButton(row,key,unit='keV'){const value=coreValue(row,key,unit);return row&&value.text!=='待补充'?`<button class="facility-value" data-evidence="${row.id}" data-key="${key}"><strong>${esc(value.text)}</strong><small>${esc(value.definition)}</small></button>`:`<span class="facility-value is-missing"><strong>${esc(value.text)}</strong><small>${esc(value.definition||'资料待补')}</small></span>`;}
function configurationCard(row,data,options){return `<section class="facility-configuration" data-configuration="${row.id}"><div class="configuration-heading">${badge(row)}<span>${esc(row.branch)}</span></div>${row.note?`<p class="branch-note facility-configuration-note"><b>配置范围与工况：</b>${esc(row.note)}</p>`:''}<div class="facility-core">${CORE_METRICS.map(key=>`<div class="facility-metric"><span class="metric-label">${CORE_LABELS[key]}</span>${metricButton(row,key,options.unit)}</div>`).join('')}</div><div class="configuration-footer"><span>${esc(row.version)} · ${row.level==='instrument'?'端站参数':'源端参数'}</span><div><a href="${esc(row.source)}" target="_blank" rel="noopener">原始资料 ↗</a><button class="facility-text-button" data-evidence="${row.id}">参数与出处</button><label class="facility-pick"><input type="checkbox" data-pick="${row.id}" aria-label="对比 ${esc(row.facility+' '+row.branch)}" ${options.chosen?.has(row.id)?'checked':''}>加入对比</label></div></div></section>`;}
function defaultCard(row,data,options,branchKey){
 if(row.category!=='history'&&row.category!=='specification')return configurationCard(row,data,options);
 const key=`baseline:${branchKey}:${row.id}`;
 return `<details class="facility-history facility-baseline" data-history="${key}" ${options.openHistory?.has(key)?'open':''}><summary>${badge(row)} <span>展开已核实的参考配置</span></summary>${configurationCard(row,data,options)}</details>`;
}
function modePanels(entry,data,options,branchKey){
 return entry.modeRows.filter(mode=>mode.row).map(mode=>{
  const content=defaultCard(mode.row,data,options,branchKey);
  if(!options.enhanced&&mode.mode!==entry.activeMode)return `<details class="facility-history"><summary>${esc(mode.mode)} · 模式参数</summary>${content}</details>`;
  return `<div data-mode-panel="${esc(branchKey)}" data-mode-name="${esc(mode.mode)}" ${mode.mode===entry.activeMode?'':'hidden'}>${content}</div>`;
 }).join('');
}
export function renderFacilityCatalogue(data,options={}){
 const groups=buildFacilityGroups(data,options);
 return energyFilterNotice(options)+(groups.map(({profile,branches,history})=>`<details class="facility-group" data-facility="${profile.id}" ${options.search||options.openFacilities?.has(profile.id)?'open':''}><summary class="facility-heading"><span class="facility-title"><strong>${esc(profile.name)}</strong><span>${esc(facilityMeta(profile,branches.length,options.level))}</span></span><span class="facility-classification">${classification(profile,branches.map(entry=>entry.branch))}</span><span class="facility-expand" aria-hidden="true">＋</span></summary><div class="facility-body">${facilityContext(profile)}${branches.map(entry=>{
  const branchKey=`${profile.id}:${entry.branch.id}`,historyKey=`history:${branchKey}`;
  return `<article class="facility-branch" data-branch="${branchKey}"><div class="branch-heading"><h2>${esc(entry.branch.name)}</h2><span class="branch-band">${esc(entry.branch.band)}</span></div>${entry.branch.description?`<p class="branch-description">${esc(entry.branch.description)}</p>`:''}<p class="branch-modes">模式：<b>${esc(entry.branch.modes.join('、'))}</b></p>${entry.branch.note?`<p class="branch-note">${esc(entry.branch.note)}</p>`:''}<div class="branch-controls"><label>参数模式<select data-branch-mode="${branchKey}" aria-label="${esc(profile.name+' '+entry.branch.name+' 参数模式')}">${entry.modes.map(mode=>`<option value="${esc(mode)}" ${mode===entry.activeMode?'selected':''}>${esc(mode)}${entry.modeRows.find(r=>r.mode===mode)?.row?'':' · 参数待补'}</option>`).join('')}</select></label><span>历史资料与其他工况见下方详情</span></div>${modePanels(entry,data,options,branchKey)}${!entry.active?`<p class="branch-empty">${esc(configurationStatus(null))}。${entry.history.length?'已收录的论文工况可在下方展开，不能作为当前能力范围。':'该模式已有分类依据，具体参数尚未收录。'}</p>`:''}${entry.history.length?`<details class="facility-history" data-history="${historyKey}" ${options.openHistory?.has(historyKey)?'open':''}><summary>历史、设计与论文工况 <span>${entry.history.length}</span></summary>${entry.history.map(row=>configurationCard(row,data,options)).join('')}</details>`:''}</article>`;
 }).join('')}${history.length?`<details class="facility-history" data-history="history:${profile.id}" ${options.openHistory?.has(`history:${profile.id}`)?'open':''}><summary>设施历史资料 <span>${history.length}</span></summary>${history.map(row=>configurationCard(row,data,options)).join('')}</details>`:''}<details class="facility-classification-evidence"><summary>分类依据与收录范围</summary><p>模式按分支与资料时期登记，分类出处如下。</p>${profile.sources.map(source=>`<p><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.title)} ↗</a><small>${esc(source.locator)}</small></p>`).join('')}<small>分类核对：${esc(profile.checkedAt)}</small></details></div></details>`).join('')||'<p class="facility-empty">没有符合条件的分支。可调整模式、目标能量或比较层级。</p>');
}
function energyFilterNotice(options){return options.energy?`<p class="branch-note facility-energy-notice"><b>目标 ${esc(options.energy)} keV 仅筛选已收录谱段，不选择工作点。</b>下列参数仍对应各自配置范围；不能将范围极值当作该能量下可同时实现的性能，未做插值。</p>`:'';}
function comparisonTable(rows,keys,data,unit){return `<table><thead><tr><th>参数</th>${rows.map(row=>`<th>${esc(row.facility)}<span>${esc(data.profiles.find(profile=>profile.id===row.display.facilityId)?.branches.find(branch=>branch.id===row.display.branchId)?.name??row.branch)} · ${esc(row.mode)}</span>${badge(row)}<small>${esc(row.version)}</small></th>`).join('')}</tr></thead><tbody>${keys.map(key=>`<tr><th>${esc(CORE_LABELS[key]??data.labels[key])}</th>${rows.map(row=>CORE_METRICS.includes(key)?`<td>${metricButton(row,key,unit)}</td>`:`<td>${known(row.metrics[key])?`<button class="facility-value" data-evidence="${row.id}" data-key="${key}"><strong>${esc(row.metrics[key].text)}</strong><small>${esc(row.metrics[key].definition)}</small></button>`:'<span class="is-missing">待补充</span>'}</td>`).join('')}</tr>`).join('')}<tr class="facility-comparison-conditions"><th>配置范围 / 工况</th>${rows.map(row=>`<td>${esc(row.note||'配置限制未另注明，请核对各项定义与出处。')}</td>`).join('')}</tr><tr><th>出处 / 工况</th>${rows.map(row=>`<td><button class="facility-text-button" data-evidence="${row.id}">查看定义、工况与出处 ↗</button></td>`).join('')}</tr></tbody></table>`;}
export function renderFacilityComparison(data,rows,options={}){
 if(!rows.length)return '<p class="facility-empty">展开设施，在需要比较的分支或历史工况中勾选“加入对比”。最多选择4项。</p>';
 return `<p class="branch-note facility-comparability-note">比较前核对原文定义：光子脉宽、带宽的 rms / FWHM 不直接等同；绝对 / 相对带宽、平均 / 峰值、设计 / 实测与源端 / 端站分别理解。各项极值不保证在同一工作点同时实现。</p>${energyFilterNotice(options)}<div class="comparison-scroll">${comparisonTable(rows,CORE_METRICS,data,options.unit)}</div><details class="facility-advanced"><summary>深入比较：电子束、加速器与波荡器</summary><div class="comparison-scroll">${comparisonTable(rows,Object.values(data.groups).flatMap(group=>group.keys).filter(key=>!['pulse','pulseEnergy','bandwidth','polarization'].includes(key)),data,options.unit)}</div></details>`;
}
export function csvText(rows,data){const quote=value=>'"'+String(value??'').replace(/^[=+@\t\r-]/,"'$&").replaceAll('"','""')+'"';const lines=[['facility','branch_id','branch','mode','stage','version','source_date','spectrum_kind','wavelength_nm','photon_energy_keV','parameter','value','definition','source','locator','evidence'],...rows.flatMap(row=>Object.entries(row.metrics).map(([key,metric])=>[row.facility,row.display.branchId,row.branch,row.mode,row.basis,row.version,row.display.sourceDate,row.spectrumKind??'capability',row.nm.join('–'),energyRange(row)?.join('–'),data.labels[key],metric.text,metric.definition,metric.source??row.source,metric.locator??row.locator,JSON.stringify(metric.evidence??row.evidence??[])]))];return '\uFEFF'+lines.map(line=>line.map(quote).join(',')).join('\r\n');}

/** Union intervals without filling gaps between branches. */
export function mergeSpectralRanges(ranges){const result=[];for(const range of ranges.map(r=>[...r]).sort((a,b)=>a[0]-b[0])){const last=result.at(-1);if(last&&range[0]<=last[1])last[1]=Math.max(last[1],range[1]);else result.push(range);}return result;}
export function buildFacilitySpectra(data,options={}){return buildFacilityGroups(data,options).map(group=>{const known=group.branches.filter(b=>b.active&&b.active.spectrumKind!=='condition'&&energyRange(b.active));const ranges=mergeSpectralRanges(known.map(b=>energyRange(b.active)));const segments=Object.entries(stagePriority).flatMap(([category])=>mergeSpectralRanges(known.filter(b=>b.active.category===category).map(b=>energyRange(b.active))).map(range=>({category,range})));return {...group,ranges,segments,knownBranches:known.length};});}
export function renderFacilitySpectrum(data,options={}){
 const groups=buildFacilitySpectra(data,options),unit=options.unit??'keV',convert=range=>unit==='nm'?[HC/range[1],HC/range[0]]:range;
 if(!groups.length)return '<p class="facility-empty">没有符合筛选条件的设施。</p>';
 const reference=data.items.filter(r=>r.level===(options.level??'source')&&r.display.role==='capability'&&r.spectrumKind!=='condition').map(r=>convert(energyRange(r)));
 const lo=reference.length?Math.floor(Math.log10(Math.min(...reference.map(r=>r[0])))):-2,hi=reference.length?Math.max(lo+1,Math.ceil(Math.log10(Math.max(...reference.map(r=>r[1]))))):2;
 const position=n=>Math.max(0,Math.min(100,(Math.log10(n)-lo)/(hi-lo)*100));
 const stageNames={operation:'运行依据',projection:'预计运行资料',specification:'设计 / 规格',history:'历史资料'};
 function bars(segments){return segments.map(({category,range})=>{const bounds=convert(range);return `<span class="spectrum-range ${category}" aria-hidden="true" style="left:${position(bounds[0])}%;width:${Math.max(.4,position(bounds[1])-position(bounds[0]))}%"></span>`;}).join('');}
 function rangeText(ranges){return ranges.length?ranges.map(convert).sort((a,b)=>a[0]-b[0]).map(r=>formatRange(r)+' '+unit).join(' / '):'参数待补';}
 const ticks=Array.from({length:hi-lo+1},(_,i)=>`<span style="left:${i/(hi-lo)*100}%">${Number((10**(lo+i)).toPrecision(3))}</span>`).join('');
 return `<div class="spectrum-legend">${Object.entries(stageNames).map(([category,label])=>`<span class="spectrum-stage ${category}">${label}</span>`).join('')}</div><div class="spectrum-axis"><span>${unit==='nm'?'波长':'光子能量'} · 对数尺度</span><div class="spectrum-ticks">${ticks}</div><span>${unit}</span></div>`+groups.map(group=>{
  const {profile,branches,ranges,segments,knownBranches}=group,categories=[...new Set(segments.map(s=>s.category))];
  return `<details class="spectrum-facility" data-spectrum-facility="${profile.id}" ${options.openSpectra?.has(profile.id)?'open':''}><summary class="spectrum-row spectrum-summary"><div class="spectrum-title"><b>${esc(profile.name)}</b><span>${esc(facilityMeta(profile,branches.length,options.level))}</span><small>${knownBranches} / ${branches.length}个${options.level==='instrument'?'端站':'分支'}已收录范围</small></div><div class="spectrum-track">${bars(segments)}</div><div class="spectrum-result"><strong>${esc(rangeText(ranges))}</strong><span>${categories.map(c=>stageNames[c]).join('、')||'资料待补'}</span><small>展开${options.level==='instrument'?'端站':'分支'} <i aria-hidden="true">＋</i></small></div></summary><div class="spectrum-body">${facilityContext(profile)}${branches.map(entry=>{const row=entry.active,range=row?energyRange(row):null;return `<article class="spectrum-branch"><div class="spectrum-row"><div><b>${esc(entry.branch.name)}</b><span>${esc(entry.activeMode)}</span>${badge(row)}</div><div class="spectrum-track">${range?bars([{category:row.category,range}]):''}</div><div class="spectrum-branch-result">${row?`<button class="facility-value" data-evidence="${row.id}" data-key="spectrum"><strong>${esc(spectrumText(row,unit))}</strong><small>查看原文依据 ↗</small></button>`:'<span class="is-missing">参数待补</span>'}</div></div>${entry.branch.description?`<p class="spectrum-branch-description">${esc(entry.branch.description)}</p>`:''}</article>`;}).join('')}</div></details>`;
 }).join('')||'<p class="facility-empty">没有符合筛选条件的设施。</p>';
}

const mounts=new WeakMap();
export function mountFacilityExplorer(root,data){
 mounts.get(root)?.();const controller=new AbortController(),signal=controller.signal,$=id=>root.querySelector('#'+id);
 const target=$('target');
 if(target&&!$('facility-energy-help')){const help=root.ownerDocument.createElement('small');help.id='facility-energy-help';help.textContent='仅筛已收录谱段，不选择工作点；参数范围不代表该能量下的性能。';target.insertAdjacentElement('afterend',help);target.setAttribute('aria-describedby',[target.getAttribute('aria-describedby'),'facility-energy-help'].filter(Boolean).join(' '));}
 const unmountAtlas=$('facilityatlas')?mountFacilityAtlas($('facilityatlas'),data):()=>{};
 let view='atlas',unit='keV',activeModes={},visibleRows=[],selected=new Set();
 function selectedRows(){return [...selected].map(id=>data.items.find(row=>row.id===id)).filter(Boolean);}
 function restoreComparison(){$('sharearea').hidden=true;$('sharebox').value='';const params=new URLSearchParams(location.hash.slice(1)),requested=params.get('compare')?.split(',').filter(Boolean)??[];selected=new Set(validSelection(requested,data.items));unit=params.get('unit')==='nm'?'nm':'keV';$('unit').value=unit;if(selected.size)$('level').value=selectedRows()[0].level;const notes=[];if(requested.length!==selected.size)notes.push('链接中部分配置无效、重复或比较层级不同，已略过；源端与实验端站请分开比较。');if(params.has('compare')&&params.get('rev')&&params.get('rev')!==data.revision)notes.push('资料版本已变化，请重新核对参数与出处。');$('message').textContent=notes.join(' ');}
 function options(){return {enhanced:true,level:$('level').value,mode:$('mode').value,search:$('search').value,energy:Number($('target').value)||null,unit,activeModes,chosen:selected,openFacilities:new Set([...root.querySelectorAll('details[data-facility][open]')].map(node=>node.dataset.facility)),openSpectra:new Set([...root.querySelectorAll('details[data-spectrum-facility][open]')].map(node=>node.dataset.spectrumFacility)),openHistory:new Set([...root.querySelectorAll('details[data-history][open]')].map(node=>node.dataset.history))};}
 function render(){const opts=options(),groups=buildFacilityGroups(data,opts);visibleRows=groups.flatMap(group=>group.branches.map(branch=>branch.active).filter(Boolean));$('catalogue').innerHTML=renderFacilityCatalogue(data,opts);$('count').textContent=`${groups.length}个设施 · ${groups.reduce((n,g)=>n+g.branches.length,0)}个${opts.level==='instrument'?'端站':'分支'}`;
  const rows=selectedRows();$('pickedcount').textContent=String(rows.length);$('compare').innerHTML=renderFacilityComparison(data,rows,opts);
  $('tray').hidden=!rows.length||view==='compare'||view==='atlas';$('traycount').textContent=`已选 ${rows.length} / 4`;$('traynames').textContent=rows.map(row=>`${row.facility} · ${row.branch}`).join('；');
  $('spectrum').innerHTML=renderFacilitySpectrum(data,opts);
 }
 function changeView(next){view=next;for(const name of ['atlas','table','compare','spectrum','coverage']){const panel=$(name+'view');if(panel)panel.hidden=name!==next;}for(const id of ['parametertools','parameterfootnote']){const node=$(id);if(node)node.hidden=next==='atlas';}root.querySelectorAll('[data-view]').forEach(button=>{button.classList.toggle('active',button.dataset.view===next);button.setAttribute('aria-pressed',String(button.dataset.view===next));});render();}
 root.addEventListener('facility:parameters',event=>{const profile=data.profiles.find(profile=>profile.id===event.detail?.facilityId);if(!profile)return;$('search').value=profile.name;$('level').value='source';$('mode').value='';$('target').value='';changeView('table');$('tableview').scrollIntoView({behavior:'smooth',block:'start'});},{signal});
 function evidenceCards(list){return list.map(ev=>`<article class="evidence-card"><small>${esc(ev.year??'日期未注明')} · ${esc(ev.type==='review'?'设施综述':ev.type==='research'?'研究论文':'官方资料')} · ${esc(ev.decision==='adopted'?'本配置采用':ev.decision==='superseded'?'历史值':'背景依据')}</small><h3><a href="${esc(ev.url)}" target="_blank" rel="noopener">${esc(ev.title)} ↗</a></h3><p>${esc(ev.authors)} · ${esc(ev.authorRole)}${ev.doi?`<br>DOI ${esc(ev.doi)}`:''}</p><p>原文值：${esc(ev.value)}<br>定位：${esc(ev.locator)}<br>工况：${esc(ev.conditions)}</p><p>采纳理由：${esc(ev.reason)}</p></article>`).join('');}
 function evidence(id,key){const row=data.items.find(row=>row.id===id);if(!row)return;const metric=row.metrics[key],profile=data.profiles.find(p=>p.id===row.display.facilityId);$('dialogtitle').textContent=`${row.facility} · ${CORE_LABELS[key]??data.labels[key]??row.branch}`;
  $('detail').innerHTML=`${badge(row)}<p>${esc(row.branch)} · ${esc(row.mode)}</p>${key?`<h3>${esc(CORE_METRICS.includes(key)?coreValue(row,key,unit).text:metric?.text??'')}</h3>`:''}${key==='rate'?`<div class="evidence-definition">${['averageRate','trainRate','intraRate','pulsesPerTrain'].map(k=>`<p><b>${esc(data.labels[k])}：</b>${esc(row.metrics[k].text)}<small>${esc(row.metrics[k].definition)}</small></p>`).join('')}</div>`:metric?.definition?`<p class="evidence-definition">${esc(metric.definition)}</p>`:''}${key==='spectrum'?'<p class="evidence-definition">波长与光子能量按 E = hc / λ 对应。论文单点工况不能表示装置能力范围；不同参数极值不保证同时实现。</p>':''}<p>${esc(row.note)}</p><dl><dt>资料版本</dt><dd>${esc(row.version)}</dd><dt>来源日期</dt><dd>${esc(row.display.sourceDate??'原文未注明')}</dd><dt>核验日期</dt><dd>${esc(row.checkedAt)}（不是运行日期）</dd><dt>定位</dt><dd>${esc(metric?.locator??row.locator)}</dd><dt>出处</dt><dd><a href="${esc(metric?.source??row.source)}" target="_blank" rel="noopener">查看原始资料 ↗</a></dd></dl>${key===undefined?`<details class="facility-advanced"><summary>完整参数与定义</summary>${Object.entries(row.metrics).map(([k,m])=>`<p><b>${esc(data.labels[k])}：</b>${esc(m.text)}<small>${esc(m.definition)}</small></p>`).join('')}</details>`:''}${evidenceCards(metric?.evidence??row.evidence??[])}<details class="facility-advanced"><summary>同分支模式与资料版本</summary>${data.items.filter(other=>other.display.facilityId===row.display.facilityId&&other.display.branchId===row.display.branchId).map(other=>`<p><button class="facility-text-button" data-evidence="${other.id}">${esc(other.branch)} · ${esc(other.version)}</button></p>`).join('')}</details>${profile?`<details class="facility-advanced"><summary>设施分类依据</summary>${profile.sources.map(source=>`<p><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.title)} ↗</a><small>${esc(source.locator)}</small></p>`).join('')}</details>`:''}`;if(!$('evidence').open)$('evidence').showModal();
 }
 function syncShare(){const hash=new URLSearchParams({compare:[...selected].join(','),unit,...(data.revision?{rev:data.revision}:{})});history.replaceState(history.state,'',location.pathname+location.search+'#'+hash);$('sharebox').value=location.href;}
 function clear(){selected.clear();$('sharearea').hidden=true;history.replaceState(history.state,'',location.pathname+location.search);render();}
 root.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.evidence)evidence(button.dataset.evidence,button.dataset.key);if(button.dataset.view)changeView(button.dataset.view);},{signal});
 root.addEventListener('change',event=>{const target=event.target;if(target.dataset.pick){const row=data.items.find(row=>row.id===target.dataset.pick);if(target.checked&&[...selected].some(id=>data.items.find(row=>row.id===id)?.level!==row?.level)){target.checked=false;$('message').textContent='源端和实验端站请分开比较，先清空已选项再切换。';return;}if(target.checked&&selected.size>=4&&!selected.has(target.dataset.pick)){target.checked=false;$('message').textContent='最多对比4项，请先取消一项。';return;}target.checked?selected.add(target.dataset.pick):selected.delete(target.dataset.pick);$('message').textContent='';if(location.hash.includes('compare='))syncShare();render();}if(target.dataset.branchMode){$('mode').value='';activeModes[target.dataset.branchMode]=target.value;render();root.querySelector(`#tableview [data-branch-mode="${target.dataset.branchMode}"]`)?.focus();}},{signal});
 for(const id of ['search','level','mode','target'])$(id).addEventListener('input',render,{signal});$('unit').addEventListener('change',()=>{unit=$('unit').value;if(location.hash.includes('compare='))syncShare();render();},{signal});
 $('reset').addEventListener('click',()=>{for(const id of ['search','mode','target'])$(id).value='';$('level').value='source';activeModes={};render();},{signal});$('clear').addEventListener('click',clear,{signal});$('trayclear').addEventListener('click',clear,{signal});$('gocompare').addEventListener('click',()=>{changeView('compare');$('compareview').scrollIntoView({behavior:'smooth',block:'start'});},{signal});$('close').addEventListener('click',()=>$('evidence').close(),{signal});$('share').addEventListener('click',()=>{syncShare();$('sharearea').hidden=false;$('sharebox').select();},{signal});
 $('csv').addEventListener('click',()=>{const rows=view==='compare'?selectedRows():visibleRows;const url=URL.createObjectURL(new Blob([csvText(rows,data)],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='feltrace-facility-parameters.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},{signal});
 $('mode').innerHTML='<option value="">全部模式</option>'+[...new Set(data.profiles.flatMap(profile=>profile.branches.flatMap(branch=>branch.modes)))].map(mode=>`<option>${esc(mode)}</option>`).join('');$('coverage').innerHTML=data.coverage.map(entry=>`<article><small>${esc(entry.group)}</small><h3>${esc(entry.name)}</h3><p>${esc(entry.gap)}</p></article>`).join('');restoreComparison();changeView(selected.size?'compare':'atlas');
 const hashChanged=()=>{restoreComparison();changeView(selected.size?'compare':'atlas');};window.addEventListener('hashchange',hashChanged,{signal});const cleanup=()=>{controller.abort();unmountAtlas();$('evidence').close();mounts.delete(root);};mounts.set(root,cleanup);return cleanup;
}
if(typeof document!=='undefined'&&document.body?.dataset.exportedAt){const root=document.querySelector('.facility-explorer'),json=document.querySelector('#facility-data');if(root&&json)mountFacilityExplorer(root,JSON.parse(json.textContent));}
